import JSZip from 'jszip';
import { DevOpsProject } from '../data/projectsData';

export async function downloadProjectAsZip(project: DevOpsProject): Promise<void> {
  const zip = new JSZip();

  // Populate files in zip folder structure
  project.files.forEach((file) => {
    zip.file(file.path, file.content);
  });

  // Add an autogenerated git-compatible info file
  zip.file('.github-info.json', JSON.stringify({
    projectName: project.title,
    author: "Madhav Gupta",
    email: "madhavgupta0594@gmail.com",
    githubRepo: project.githubUrl,
    generatedAt: new Date().toISOString(),
    filesCount: project.files.length,
    techStack: project.techStack
  }, null, 2));

  // Generate ZIP blob
  const content = await zip.generateAsync({ type: 'blob' });
  const downloadUrl = URL.createObjectURL(content);

  // Trigger browser download
  const link = document.createElement('a');
  link.href = downloadUrl;
  link.download = `${project.id}-github-repo.zip`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  setTimeout(() => {
    URL.revokeObjectURL(downloadUrl);
  }, 1000);
}
